/** CJK 词之间不要空格 */
export function joinWords(words) {
  return words.reduce((acc, w) => {
    const t = String(w.text ?? '');
    if (!t) return acc;
    const prev = acc.slice(-1);
    const cjk = /[\u3000-\u9fff\uff00-\uffef]/;
    if (prev && cjk.test(prev) && cjk.test(t[0])) return acc + t;
    if (!prev) return t;
    return acc + ' ' + t;
