  const CONF = { '额': '数', '額': '数', '貊': '据', '袤': '表', '榈': '树', '笥': '结', '枥': '构', '甙': '式', '丌': '开', '仝': '全', '囗': '口', '菘': '随', '隨': '随', '〇': '0', 'О': '0', 'Ｏ': '0', 'ｌ': '1', '丨': '1', '數': '数', '據': '据', '結': '结', '構': '构', '掏': '构', '統': '统', '訊': '讯', '隨': '随', '學': '学', '點': '点', '規': '规', '則': '则' };
